with open("/app/dataset/genealogy_trees.txt", "r") as f:
    lines = [line.rstrip('\n') for line in f.readlines()]

def get_char(r, c):
    if 0 <= r < len(lines) and 0 <= c < len(lines[r]):
        return lines[r][c]
    return ' '

def is_line_char(char):
    return char in '|│+-~-~\\/=_'

def find_person_by_coord(r, c):
    for p in people:
        if p["r1"] - 3 <= r <= p["r2"] + 3:
            c_min = min(p["c1"], p["c2"]) - 10
            c_max = max(p["c1"] + len(p["first_name"]), p["c2"] + len(p["last_name"])) + 10
            if c_min <= c <= c_max:
                return p
    return None

def find_parent(p_child):
    c1 = p_child["c1"]
    r1 = p_child["r1"] - 1

    start_r = None
    start_c = None
    for r_offset in range(1, 5):
        test_r = r1 - r_offset
        for c_offset in range(-5, 15):
            test_c = c1 + c_offset
            char = get_char(test_r, test_c)
            if char in '|│':
                start_r = test_r
                start_c = test_c
                break
        if start_r is not None:
            break

    if start_r is None:
        return None

    curr_r = start_r
    curr_c = start_c

    visited = set()
    while curr_r >= 0:
        if (curr_r, curr_c) in visited:
            break
        visited.add((curr_r, curr_c))

        parent = find_person_by_coord(curr_r, curr_c)
        if parent and (parent["first_name"] != p_child["first_name"] or parent["last_name"] != p_child["last_name"]):
            return parent

        next_r = curr_r - 1
        found_next = False
        for c_offset in [0, -1, 1, -2, 2]:
            test_c = curr_c + c_offset
            char = get_char(next_r, test_c)
            if is_line_char(char):
                curr_r = next_r
                curr_c = test_c
                found_next = True
                break

        if not found_next:
            is_bar = False
            bar_chars = 0
            for col in range(curr_c - 10, curr_c + 11):
                if get_char(curr_r, col) in '-+~_':
                    bar_chars += 1
            if bar_chars > 5:
                is_bar = True

            if is_bar:
                left_edge = curr_c
                while left_edge >= 0 and (get_char(curr_r, left_edge) != ' ' or any(get_char(curr_r, col) != ' ' for col in range(left_edge-3, left_edge))):
                    left_edge -= 1
                left_edge += 1

                right_edge = curr_c
                while right_edge < len(lines[curr_r]) and (get_char(curr_r, right_edge) != ' ' or any(get_char(curr_r, col) != ' ' for col in range(right_edge, right_edge+3))):
                    right_edge += 1
                right_edge -= 1

                up_v_col = None
                for row_up in [curr_r - 1, curr_r - 2, curr_r - 3]:
                    for col in range(left_edge, right_edge + 1):
                        if get_char(row_up, col) in '|│':
                            up_v_col = col
                            up_v_row = row_up
                            break
                    if up_v_col is not None:
                        break

                if up_v_col is not None:
                    curr_r = up_v_row
                    curr_c = up_v_col
                else:
                    break
            else:
                skipped = False
                for skip in range(1, 4):
                    test_r = curr_r - skip
                    for c_offset in [0, -1, 1, -2, 2]:
                        test_c = curr_c + c_offset
                        if is_line_char(get_char(test_r, test_c)):
                            curr_r = test_r
                            curr_c = test_c
                            skipped = True
                            break
                    if skipped:
                        break
                if not skipped:
                    break

    return None

# Dictionary to store parent of each person
# Key: "First Last", Value: "First Last" of parent
parent_map = {}
for idx, p in enumerate(people):
    name = f"{p['first_name']} {p['last_name']}"
    parent = find_parent(p)
    if parent:
        parent_name = f"{parent['first_name']} {parent['last_name']}"
        parent_map[name] = parent_name
    else:
        parent_map[name] = None
    if (idx + 1) % 50 == 0 or idx + 1 == len(people):
        print(f"Traced parent for {idx+1}/{len(people)} people...")

# Build children map
children_map = {}
for p in people:
    name = f"{p['first_name']} {p['last_name']}"
    if name not in children_map:
        children_map[name] = []

for child_name, parent_name in parent_map.items():
    if parent_name:
        if parent_name not in children_map:
            children_map[parent_name] = []
        children_map[parent_name].append(child_name)

# Let's save the parent map and children map to check
with open("/app/parent_map.json", "w") as f:
    json.dump(parent_map, f, indent=2)

with open("/app/children_map.json", "w") as f:
    json.dump(children_map, f, indent=2)

print("Tree building complete.")

