        curr_c = start_c

        visited = set()
        while curr_r >= 0:
            if (curr_r, curr_c) in visited:
                break
            visited.add((curr_r, curr_c))

            parent = find_person_by_coord(curr_r, curr_c)
            if parent and parent["name"] != p_child["name"]:
                return parent

            next_r = curr_r - 1
            found_next = False
            for c_offset in [0, -1, 1, -2, 2]:
                test_c = curr_c + c_offset
                char = get_char(next_r, test_c)
                if is_line_char(char):
