                    left_edge = curr_c
                    while left_edge >= 0 and (get_char(curr_r, left_edge) != ' ' or any(get_char(curr_r, col) != ' ' for col in range(left_edge-3, left_edge))):
                        left_edge -= 1
                    left_edge += 1

                    right_edge = curr_c
                    while right_edge < len(lines[curr_r]) and (get_char(curr_r, right_edge) != ' ' or any(get_char(curr_r, col) != ' ' for col in range(right_edge, right_edge+3))):
                        right_edge += 1
                    right_edge -= 1

                    up_v_col = None
                    for row_up in [curr_r - 1, curr_r - 2, curr_r - 3]:
                        for col in range(left_edge, right_edge + 1):
                            if get_char(row_up, col) in '|│':
                                up_v_col = col
                                up_v_row = row_up
                                break
                        if up_v_col is not None:
                            break

                    if up_v_col is not None:
                        curr_r = up_v_row
                        curr_c = up_v_col
                    else:
                        break
                else:
                    skipped = False
                    for skip in range(1, 4):
                        test_r = curr_r - skip
                        for c_offset in [0, -1, 1, -2, 2]:
                            test_c = curr_c + c_offset
                            if is_line_char(get_char(test_r, test_c)):
                                curr_r = test_r
                                curr_c = test_c
                                skipped = True
                                break
                        if skipped:
                            break
                    if not skipped:
                        break

        return None

    # Build children map dynamically
    children_map = {}
    for p in people_coords:
        children_map[p["name"]] = []

    for p in people_coords:
        parent = find_parent(p)
        if parent:
            if parent["name"] not in children_map:
                children_map[parent["name"]] = []
            children_map[parent["name"]].append(p["name"])

    # Trace great-great-grandparent of 'Dawid Majtyka'
    current_person = find_person_by_coord(92, 2955) # Row of Dawid Majtyka is 93 (0-based 92)
    ancestor = current_person
    for _ in range(4): # 4 generations up to great-great-grandparent
        ancestor = find_parent(ancestor)

    # Przemysław Kurczab is the ancestor
    direct_children = children_map.get(ancestor["name"], [])

    total_balance = 0
    for child in direct_children:
        # Find grandchildren of this child
        child_children = children_map.get(child, [])
        child_grandchildren = []
        for cc in child_children:
            child_grandchildren.extend(children_map.get(cc, []))

        if len(child_grandchildren) > 1:
            total_balance += people_db[child]

    return total_balance

